SOURCES = {'pose': 'package pose\nimport("testing";"os";"path/filepath";"strings";"time")\nfunc TestB07R3AncestorSymlink(t *testing.T){\n root:=snapshotRepo(t,map[string]string{"src/lib.go":"sealed"});head:=snapshotGit(t,root,"rev-parse","HEAD")\n if d,e:=WorktreeDivergence(root,head,nil);e!=nil||len(d)>0{t.Fatalf("control %v %v",d,e)}\n outside:=filepath.Join(t.TempDir(),"src");if e:=os.Rename(filepath.Join(root,"src"),outside);e!=nil{t.Fatal(e)};if e:=os.Symlink(outside,filepath.Join(root,"src"));e!=nil{t.Fatal(e)}\n d,e:=WorktreeDivergence(root,head,nil);t.Logf("ancestor symlink divergence=%v err=%v",d,e);if e==nil&&len(d)==0{t.Error("ancestor symlink escaping root accepted")}\n}\nfunc TestB07R3CheckpointScope(t *testing.T){\n name:=".pose/closeout-plans/not-this-scope.json";root:=snapshotRepo(t,map[string]string{name:"sealed"});os.WriteFile(filepath.Join(root,name),[]byte("changed"),0644)\n d,e:=(Store{Root:root}).ungeneratedChanges();t.Logf("arbitrary checkpoint dirty=%v err=%v",d,e);if e==nil&&len(d)==0{t.Error("modified unrelated checkpoint accepted as generated")}\n}\nfunc TestB07R3TiedBundleLostAttestation(t *testing.T){\n s,old,now:=retentionFixture(t);p:=filepath.Join(s.Root,".pose/review-profiles/spec-closeout.json");raw,_:=os.ReadFile(p);var next ReviewBundle\n for i:=1;i<=100;i++{os.WriteFile(p,append(append([]byte{},raw...),[]byte(strings.Repeat(" ",i))...),0644);b,e:=s.SealReviewBundle("spec:backend",now);if e!=nil{t.Fatal(e)};if b.BundleID<old.BundleID{next=b;break}}\n if next.BundleID==""{t.Fatal("no lower hash")};reject:=approvedBundleAttestation(next,"agent:reject");reject.Decision="changes-requested";att,e:=s.RecordReviewAttestation(reject,now.Add(time.Minute));if e!=nil{t.Fatal(e)}\n closeBackendSpec(t,s);addMatrixCheck(t,s);v,e:=s.VerifyReviewBundle("spec:backend");if e!=nil||v.Approved{t.Fatalf("negative control approved=%v err=%v",v.Approved,e)}\n p=filepath.Join(s.Root,filepath.FromSlash(att.Path));data,e:=os.ReadFile(p);if e!=nil{t.Fatal(e)};data=[]byte(strings.Replace(string(data),`"decision": "changes-requested"`,`"decision": 17`,1));os.WriteFile(p,data,0644)\n read,_:=s.ReadReviewAttestations(next.BundleID);t.Logf("loss=%+v",read.Coverage)\n v,e=s.VerifyReviewBundle("spec:backend");t.Logf("lost rejection approved=%v state=%s err=%v",v.Approved,v.State,e);if e==nil&&v.Approved{t.Error("approval retained over lost tied sibling attestation")}\n}\nfunc TestB07R3SnapshotRecoversUnknown(t *testing.T){\n root:=snapshotRepo(t,map[string]string{".pose/project.json":`{"schema_version":1,"project_id":"proj.probe"}`,"a":"a"});s:=Store{Root:root};p:=filepath.Join(root,".git/index");raw,_:=os.ReadFile(p);os.WriteFile(p,[]byte("broken"),0644);before:=s.CurrentObligationSnapshot();os.WriteFile(p,raw,0644)\n changed:=s.ObligationSnapshotChanges(before);t.Logf("before coherent=%v now=%v changes=%v",before.Coherent,s.CurrentObligationSnapshot().Coherent,changed);if !before.Coherent&&len(changed)==0{t.Error("unknown baseline revalidated as unchanged after recovery")}\n}\nfunc TestB07R3RunFields(t *testing.T){\n s,b,_:=retentionFixture(t);run:=ReviewRun{RunID:"rrn-probe",Status:ReviewRunCompleted,Scope:"spec:backend",BundleID:b.BundleID,BundleDigest:"sha256:wrong",SealedCommit:"wrong",PolicyDigest:directoryDigest(filepath.Join(s.Root,".pose/policy"))}\n reason:=s.ReviewRunStillGoverns(run);t.Logf("wrong digest and commit reason=%q",reason);if reason==""{t.Error("run with wrong digest and commit governs")}\n}\nfunc TestB07R3LostSupersedingRun(t *testing.T){\n s,b,now:=retentionFixture(t);base:=ReviewRun{SchemaVersion:1,Status:ReviewRunCompleted,Scope:"spec:backend",BundleID:b.BundleID,BundleDigest:b.BundleDigest,SealedCommit:b.Payload.Subject.Head,PolicyDigest:directoryDigest(filepath.Join(s.Root,".pose/policy")),StartedAt:now.Format(time.RFC3339Nano),EndedAt:now.Format(time.RFC3339Nano)}\n run,e:=s.recordReviewRun(base,nil);if e!=nil{t.Fatal(e)};if why:=s.ReviewRunStillGoverns(run);why!=""{t.Fatalf("control %s",why)}\n late:=base;late.Status=ReviewRunStale;late.Supersedes=run.RunID;late.Failure="stale";late.EndedAt=now.Add(time.Second).Format(time.RFC3339Nano);sup,e:=s.recordReviewRun(late,nil);if e!=nil{t.Fatal(e)}\n if why:=s.ReviewRunStillGoverns(run);why==""{t.Fatal("supersession control accepted")};p:=filepath.Join(s.Root,sup.Path);raw,_:=os.ReadFile(p);os.WriteFile(p,append(raw,[]byte("broken")...),0644)\n why:=s.ReviewRunStillGoverns(run);t.Logf("lost superseding run reason=%q",why);if why==""{t.Error("lost superseding run treated as absent")}\n}\nfunc TestB07R3ConfigRedirect(t *testing.T){\n root:=snapshotRepo(t,map[string]string{"lib.go":"sealed"});head:=snapshotGit(t,root,"rev-parse","HEAD");other:=t.TempDir();os.WriteFile(filepath.Join(other,"lib.go"),[]byte("sealed"),0644);os.WriteFile(filepath.Join(root,"lib.go"),[]byte("changed"),0644)\n t.Setenv("GIT_CONFIG_COUNT","1");t.Setenv("GIT_CONFIG_KEY_0","core.worktree");t.Setenv("GIT_CONFIG_VALUE_0",other)\n d,e:=WorktreeDivergence(root,head,nil);entries,se:=ReadGitStatus(root);t.Logf("config redirect divergence=%v/%v status=%v/%v",d,e,entries,se);if e==nil&&len(d)==0{t.Error("changed root verified against config-redirected worktree")}\n}\nfunc TestB07R3QuotedGitlink(t *testing.T){\n root:=snapshotRepo(t,map[string]string{"a":"a"});head:=snapshotGit(t,root,"rev-parse","HEAD");p:="pose-mcp/module é";snapshotGit(t,root,"update-index","--add","--cacheinfo","160000,"+head+","+p);snapshotGit(t,root,"commit","-qm","pin");got:=reviewBundleGitlinks(root,[]string{p});t.Logf("quoted gitlink mapping=%v",got);if got[p]!=""{t.Log("mapping is present")}\n}\nfunc TestB07R3CustomResultsPath(t *testing.T){\n root:=snapshotRepo(t,map[string]string{".pose/results/custom.json":"old",".pose/policy/delivery.json":`{"schema_version":1,"enabled":true,"results_path":".pose/results/custom.json"}`});os.WriteFile(filepath.Join(root,".pose/results/custom.json"),[]byte("new"),0644);d,e:=(Store{Root:root}).ungeneratedChanges();t.Logf("custom producer output dirty=%v err=%v",d,e);if e!=nil||len(d)!=1{t.Fatalf("expected conservative refusal %v %v",d,e)}\n}\nfunc TestB07R3RootWhitespace(t *testing.T){\n original:=snapshotRepo(t,map[string]string{"lib.go":"sealed"});base:=t.TempDir();root:=filepath.Join(base,"repo ");if e:=os.Rename(original,root);e!=nil{t.Fatal(e)};head:=snapshotGit(t,root,"rev-parse","HEAD");snapshotGit(t,base,"clone","-q",root,filepath.Join(base,"repo"));os.WriteFile(filepath.Join(root,"lib.go"),[]byte("changed"),0644)\n entries,se:=ReadGitStatus(root);if se!=nil||len(entries)==0{t.Fatalf("dirty control %v %v",entries,se)}\n d,e:=WorktreeDivergence(root,head,nil);t.Logf("trailing-space root divergence=%v err=%v",d,e);if e==nil&&len(d)==0{t.Error("root whitespace trimmed into another clean repository")}\n}\n', 'cli': 'package cli\nimport("testing";"strings";"os";"os/exec";"path/filepath";posemodel "github.com/harne8/pose-mcp/internal/pose")\nfunc TestB07R3DispatchAncestorLink(t *testing.T){\n root:=dispatchInstance(t);outside:=filepath.Join(t.TempDir(),"moved")\n writeReviewers(t,root,map[string]posemodel.ReviewerAdapter{"probe":{Command:[]string{"sh","-c","cat >/dev/null; mv pose-mcp \'"+outside+"\'; ln -s \'"+outside+"\' pose-mcp; echo decision: approved"},Vendor:"test",Model:"probe",Timeout:"30s"}})\n code,out:=dispatchOnce(t,root,"probe");t.Logf("code=%d output=%s",code,out);if strings.Contains(out,"review_dispatch.status=completed"){t.Error("dispatch completed after ancestor escaped worktree")}\n}\nfunc TestB07R3SourceModeUnknown(t *testing.T){\n root:=dispatchInstance(t);real,e:=exec.LookPath("git");if e!=nil{t.Fatal(e)};bin:=t.TempDir()\n body:="#!/bin/sh\\ncase \\"$*\\" in *\\"-C "+root+" ls-tree\\"*) exit 97;; esac\\nexec \'"+real+"\' \\"$@\\"\\n";os.WriteFile(filepath.Join(bin,"git"),[]byte(body),0755);t.Setenv("PATH",bin+string(os.PathListSeparator)+os.Getenv("PATH"))\n writeReviewers(t,root,map[string]posemodel.ReviewerAdapter{"probe":{Command:[]string{"sh","-c","cat >/dev/null; git -C \'"+root+"\' config core.filemode false; chmod +x \'"+root+"/pose-mcp/lib.go\'; echo decision: approved"},Vendor:"test",Model:"probe",Timeout:"30s"}})\n code,out:=dispatchOnce(t,root,"probe");t.Logf("code=%d output=%s",code,out);if strings.Contains(out,"review_dispatch.status=completed"){t.Error("unreadable source mode accepted")}\n}\nfunc TestB07R3SourceType(t *testing.T){\n root:=dispatchInstance(t)\n writeReviewers(t,root,map[string]posemodel.ReviewerAdapter{"probe":{Command:[]string{"sh","-c","cat >/dev/null; git -C \'"+root+"\' update-index --assume-unchanged pose-mcp/lib.go; cp \'"+root+"/pose-mcp/lib.go\' \'"+root+"/copy.txt\'; printf \'\\\\ncopy.txt\\\\n\' >> \'"+root+"/.git/info/exclude\'; rm \'"+root+"/pose-mcp/lib.go\'; ln -s ../copy.txt \'"+root+"/pose-mcp/lib.go\'; echo decision: approved"},Vendor:"test",Model:"probe",Timeout:"30s"}})\n code,out:=dispatchOnce(t,root,"probe");t.Logf("code=%d output=%s",code,out);if strings.Contains(out,"review_dispatch.status=completed"){t.Error("source regular file replaced by symlink accepted")}\n}\nfunc TestB07R3DispatchIgnoredAncestorLink(t *testing.T){\n root:=dispatchInstance(t);outside:=filepath.Join(t.TempDir(),"moved")\n writeReviewers(t,root,map[string]posemodel.ReviewerAdapter{"probe":{Command:[]string{"sh","-c","cat >/dev/null; mv pose-mcp \'"+outside+"\'; ln -s \'"+outside+"\' pose-mcp; printf \'\\\\npose-mcp\\\\n\' >> .git-ignore-unused; rm .git-ignore-unused; git rev-parse --git-path info/exclude | xargs sh -c \'printf \\"\\\\npose-mcp\\\\n\\" >> \\"$0\\"\'; echo decision: approved"},Vendor:"test",Model:"probe",Timeout:"30s"}})\n code,out:=dispatchOnce(t,root,"probe");t.Logf("code=%d output=%s",code,out);if strings.Contains(out,"review_dispatch.status=completed"){t.Error("ignored ancestor link escapes worktree")}\n}\nfunc TestB07R3PersistedRunIdentity(t *testing.T){\n root:=dispatchInstance(t);writeReviewers(t,root,map[string]posemodel.ReviewerAdapter{"probe":{Command:[]string{"sh","-c","cat >/dev/null; echo decision: approved"},Vendor:"test",Model:"probe",Timeout:"30s"}})\n code,out:=dispatchOnce(t,root,"probe");if code!=0{t.Fatalf("control: %s",out)};s:=posemodel.Store{Root:root};runs,e:=s.ListReviewRuns("");if e!=nil||len(runs)!=1{t.Fatalf("%v %v",runs,e)};r:=runs[0]\n if why:=s.ReviewRunStillGoverns(r);why!=""{t.Fatalf("control: %s",why)}\n p:=filepath.Join(root,r.Path);raw,e:=os.ReadFile(p);if e!=nil{t.Fatal(e)};raw=[]byte(strings.Replace(string(raw),r.BundleDigest,"sha256:wrong",1));os.WriteFile(p,raw,0644);runs,e=s.ListReviewRuns("");if e!=nil||len(runs)!=1{t.Fatalf("%v %v",runs,e)}\n why:=s.ReviewRunStillGoverns(runs[0]);t.Logf("persisted run wrong digest=%q governs=%q",runs[0].BundleDigest,why);if why==""{t.Error("persisted wrong bundle digest governs")}\n}\n'}
root=pathlib.Path.cwd()
with tempfile.TemporaryDirectory(prefix='b07r3-review-') as tmp:
    base=pathlib.Path(tmp)
    for module in ('pose-mcp','mcp-enforce'):
        shutil.copytree(root/module,base/module,ignore=shutil.ignore_patterns('.git','node_modules','*.test'))
    for pkg,source in SOURCES.items():
        (base/'pose-mcp/internal'/pkg/'b07r3_review_test.go').write_text(source)
    result=subprocess.run(['go','test','./internal/pose','./internal/cli','-run','^TestB07R3','-count=1','-v'],cwd=base/'pose-mcp')
    raise SystemExit(result.returncode)
